#!/bin/zsh
cd "$(dirname "$0")"
D="$(pwd)/gen"
S="ESTILO: pixel art de videojuego estilo Pokémon Esmeralda (Game Boy Advance) pero en alta resolución, vista desde arriba en 3/4 como los muebles de interior de Pokémon, colores pastel brillantes y muy tiernos, contornos oscuros limpios. SIN texto, SIN letras, SIN números, SIN marcas de agua."
KEY="El FONDO debe ser magenta puro liso (#FF00FF) en toda la imagen, sin degradado, sin sombras en el fondo; cada objeto bien separado con mucho espacio magenta alrededor. No uses magenta dentro de los dibujos."
run(){ name=$1; shift; (codex exec --dangerously-bypass-approvals-and-sandbox --skip-git-repo-check "Usa tu herramienta de generación de imágenes. $* Al final imprime NOMBRE => RUTA COMPLETA de cada imagen generada (aunque no hayas podido copiarla)." < /dev/null > log4-$name.txt 2>&1; echo "DONE $name $?") & }
CAT="EXACTAMENTE 8 cuadros del MISMO gatito en 2 filas de 4, todos del mismo tamaño, estilo chibi tierno de Pokémon: Fila 1: sentado de frente, caminando hacia la IZQUIERDA (pata adelante), caminando hacia la IZQUIERDA (patas juntas), durmiendo enroscado como bolita. Fila 2: sentado lamiéndose la patita, caminando hacia la DERECHA (pata adelante), caminando hacia la DERECHA (patas juntas), estirándose feliz."
run aceituna "$S $KEY Crea aceituna.png (imagen ancha 16:9) en $D/: $CAT El gatito ACEITUNA es completamente NEGRO, con ojos grandes verde aceituna brillantes, naricita rosa y un collar verde con cascabel dorado."
run coco "$S $KEY Crea coco.png (imagen ancha 16:9) en $D/: $CAT El gatito COCO es BLANCO con manchas CAFÉS (una mancha café en un ojo, en la espalda y la cola café), ojos grandes color miel, naricita rosa y un collar azul con cascabel dorado."
run furn1 "$S $KEY Crea furn-a.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 12 muebles en 3 filas de 4, cada uno del mismo tamaño: cama individual rosa con almohada de corazón, ropero de madera blanco, sofá rosa de dos plazas, televisión sobre mueble, librero lleno de libros de colores, escritorio con lamparita, cama redonda para gatos con cojín, árbol rascador para gatos de dos pisos, pecera con pececitos, piano de pared blanco, baúl de juguetes abierto con peluches, platos de comida y agua para gato."
run furn2 "$S $KEY Crea furn-b.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 12 muebles en 3 filas de 4, cada uno del mismo tamaño: mesa de comedor redonda con dos sillas, refrigerador de cocina pastel, estufa de cocina, lámpara de pie, maceta grande con planta, espejo de cuerpo completo, puf redondo de colores, casita de muñecas, tocador con espejo, chimenea de ladrillo encendida, estante con peluches, cama de princesa con dosel rosa."
run furn3 "$S $KEY Crea furn-c.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño: tapete redondo rosa, tapete rectangular azul con estrellas, alfombra de corazón, cojín grande para el piso, mesita de noche con lámpara, columpio de interior para niños, tienda de campaña de juguete (tipi), consola de videojuegos con televisión pequeña."
run bld "$S $KEY Crea homebld.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 edificios en una fila, vistos desde arriba en 3/4 estilo pueblo de Pokémon, con su puerta al frente abajo: 1) la CASA DE LUCY: casita encantadora de dos pisos con techo rosa, paredes crema, flores en las ventanas, buzón con corazón y un gatito negro y uno blanco con manchas cafés en la ventana; 2) una MUEBLERÍA: tienda con toldo morado y un sofá y una lámpara en el escaparate."
wait
echo ALLDONE
